/* gphoto2-endian.h — Android replacement for the autogenerated one.
 * Adapted from upstream libgphoto2/gphoto2-endian.h.in for a LITTLE-ENDIAN,
 * 64/32-bit ARM Android target. Available since both arm64-v8a and
 * armeabi-v7a are little-endian. */
#ifndef GP_BYTEORDER_H
#define GP_BYTEORDER_H

#include <stdint.h>
#include <endian.h>
#include <arpa/inet.h>

/* generic (compiler) byte swapping */
#define swap16(x) __builtin_bswap16(x)
#define swap32(x) __builtin_bswap32(x)
#define swap64(x) __builtin_bswap64(x)

#define __HAVE_NTOHL

/* aliases for the standard swapping macros (little endian host) */
#ifndef htobe16
# define htobe16(x) htons(x)
#endif
#ifndef htobe32
# define htobe32(x) htonl(x)
#endif
#ifndef be16toh
# define be16toh(x) htobe16(x)
#endif
#ifndef be32toh
# define be32toh(x) htobe32(x)
#endif

#define HTOBE16(x) (x) = htobe16(x)
#define HTOBE32(x) (x) = htobe32(x)
#define BE32TOH(x) (x) = be32toh(x)
#define BE16TOH(x) (x) = be16toh(x)

/* little-endian: these are identity operations */
#ifndef htole16
# define htole16(x) (x)
#endif
#ifndef htole32
# define htole32(x) (x)
#endif
#ifndef htole64
# define htole64(x) (x)
#endif
#ifndef le16toh
# define le16toh(x) (x)
#endif
#ifndef le32toh
# define le32toh(x) (x)
#endif
#ifndef le64toh
# define le64toh(x) (x)
#endif

#define HTOLE16(x) (void) (x)
#define HTOLE32(x) (void) (x)
#define HTOLE64(x) (void) (x)
#define LE16TOH(x) (void) (x)
#define LE32TOH(x) (void) (x)
#define LE64TOH(x) (void) (x)

#define HTOBE64(x) (x) = swap64(x)
#define BE64TOH(x) (x) = swap64(x)

/* C99 types were pulled in above */
#include <stdint.h>

/* integer-from-byte-array helpers (portable, no unaligned casts) */
#define be16atoh(x)  ((uint16_t)(((x)[0]<<8)|(x)[1]))
#define be32atoh(x)  ((uint32_t)(((x)[0]<<24)|((x)[1]<<16)|((x)[2]<<8)|(x)[3]))
#define be64atoh_x(x,off,shift) (((uint64_t)((x)[off]))<<shift)
#define be64atoh(x)  ((uint64_t)(be64atoh_x(x,0,56)|be64atoh_x(x,1,48)| \
        be64atoh_x(x,2,40)|be64atoh_x(x,3,32)|be64atoh_x(x,4,24)| \
        be64atoh_x(x,5,16)|be64atoh_x(x,6,8)|((x)[7])))
#define le16atoh(x)  ((uint16_t)(((x)[1]<<8)|(x)[0]))
#define le32atoh(x)  ((uint32_t)(((x)[3]<<24)|((x)[2]<<16)|((x)[1]<<8)|(x)[0]))
#define le64atoh_x(x,off,shift) (((uint64_t)(x)[off])<<shift)
#define le64atoh(x)  ((uint64_t)(le64atoh_x(x,7,56)|le64atoh_x(x,6,48)| \
        le64atoh_x(x,5,40)|le64atoh_x(x,4,32)|le64atoh_x(x,3,24)| \
        le64atoh_x(x,2,16)|le64atoh_x(x,1,8)|((x)[0])))

#define htobe16a(a,x) (a)[0]=(uint8_t)((x)>>8), (a)[1]=(uint8_t)(x)
#define htobe32a(a,x) (a)[0]=(uint8_t)((x)>>24), (a)[1]=(uint8_t)((x)>>16), \
    (a)[2]=(uint8_t)((x)>>8), (a)[3]=(uint8_t)(x)
#define htobe64a(a,x) (a)[0]=(uint8_t)((x)>>56), (a)[1]=(uint8_t)((x)>>48), \
    (a)[2]=(uint8_t)((x)>>40), (a)[3]=(uint8_t)((x)>>32), \
    (a)[4]=(uint8_t)((x)>>24), (a)[5]=(uint8_t)((x)>>16), \
    (a)[6]=(uint8_t)((x)>>8), (a)[7]=(uint8_t)(x)
#define htole16a(a,x) (a)[1]=(uint8_t)((x)>>8), (a)[0]=(uint8_t)(x)
#define htole32a(a,x) (a)[3]=(uint8_t)((x)>>24), (a)[2]=(uint8_t)((x)>>16), \
    (a)[1]=(uint8_t)((x)>>8), (a)[0]=(uint8_t)(x)
#define htole64a(a,x) (a)[7]=(uint8_t)((x)>>56), (a)[6]=(uint8_t)((x)>>48), \
    (a)[5]=(uint8_t)((x)>>40), (a)[4]=(uint8_t)((x)>>32), \
    (a)[3]=(uint8_t)((x)>>24), (a)[2]=(uint8_t)((x)>>16), \
    (a)[1]=(uint8_t)((x)>>8), (a)[0]=(uint8_t)(x)

#endif /* GP_BYTEORDER_H */
